import React, { useState } from 'react';
import { useAppDispatch, useAppSelector } from '../store/hooks';
import { fetchArticles } from '../store/newsSlice';
import { InputGroup, FormControl, Button } from 'react-bootstrap';

const SearchBar: React.FC = () => {
  const [query, setQuery] = useState('');
  const dispatch = useAppDispatch();
  const { source, date, category, author } = useAppSelector((state) => state.news); // ✅ Get author from Redux state

  const handleSearch = () => {
    dispatch(fetchArticles({ query, source, date, category, author })); // ✅ Pass all required parameters
  };

  return (
    <div className="search-bar my-3">
      <InputGroup className="mb-3">
        <FormControl
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search news..."
        />
        <Button variant="primary" onClick={handleSearch}>Search</Button>
      </InputGroup>
    </div>
  );
};

export default SearchBar;
